    if(resType)resHtml+='<div id="lc-type2" style="display:inline-block;margin-bottom:8px;font-family:var(--fh);font-size:9px;letter-spacing:1px;padding:4px 11px;border-radius:99px;color:var(--gold);background:rgba(192,160,80,.12);border:1px solid rgba(192,160,80,.4)">'+esc(resType)+'</div><br>';
    if(resources.length)resHtml+='<div class="lc-tags">'+resources.map(function(x){return '<span class="lc-tag">'+esc(x)+'</span>';}).join('')+'</div>';
  }else{
    resHtml='<div class="lc-note" style="border-left-color:var(--mu)">'+t(STR.noResource)+'</div>';
  }
  g('res-wrap').innerHTML=resHtml;

  // threats
  var present=!!d.monstersPresent;
  var threatHtml='<div class="lc-threat-row"><div class="lc-threat-icon '+(present?'on':'off')+'">'+
    (present
      ? '<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M8 2 L14.5 13.4 H1.5 Z" stroke="var(--danger)" stroke-width="1.2" fill="none" stroke-linejoin="round"/><line x1="8" y1="6.4" x2="8" y2="9.8" stroke="var(--danger)" stroke-width="1.3" stroke-linecap="round"/><circle cx="8" cy="11.5" r=".9" fill="var(--danger)"/></svg>'
      : '<svg width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M3 8.5 L6.5 12 L13 4.5" stroke="var(--ac)" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>')+
    '</div><div class="lc-threat-text'+(present?' on':'')+'">'+
    (present ? esc(d.monsterNote||t(STR.threatKnown)) : t(STR.noThreat))+
    '</div></div>';
  if(present&&d.monsterTypes&&d.monsterTypes.length){
    threatHtml+='<div class="lc-tags" style="margin-top:9px">'+d.monsterTypes.map(function(x){return '<span class="lc-tag danger">'+esc(x)+'</span>';}).join('')+'</div>';
  }
  g('threat-wrap').innerHTML=threatHtml;

  // map
  var img=g('lc-map-img');
  if(d.mapImage){img.src='https://files.catbox.moe/'+d.mapImage;img.style.display='block';img.onerror=function(){img.style.display='none'};}
  else{img.style.display='none';img.removeAttribute('src');}

  var zones=(d.zones||[]).map(function(z){
    return {x:clamp(parseFloat(z.x)||0,6,94),y:clamp(parseFloat(z.y)||0,8,92),type:z.type,label:z.label||''};
  });

  var pinsEl=g('lc-map-pins');
  var linesEl=g('lc-map-lines');
  var emptyEl=g('lc-map-empty');
  var legEl=g('lc-legend');

  if(!zones.length){
    pinsEl.innerHTML='';linesEl.innerHTML='';legEl.innerHTML='';
    emptyEl.style.display='flex';
  }else{
    emptyEl.style.display='none';
    pinsEl.innerHTML=zones.map(function(z){
      var zt=zoneType(z.type);
      return '<div class="lc-pin" style="left:'+z.x+'%;top:'+z.y+'%">'+
        '<div class="lc-pin-badge" style="--pc:'+zt.color+'"><svg width="12" height="12" viewBox="0 0 16 16" fill="none" style="color:'+zt.color+'">'+zt.icon+'</svg></div>'+
        (z.label?'<div class="lc-pin-label">'+esc(z.label)+'</div>':'')+
        '</div>';
    }).join('');

    if(zones.length>1){
      var pts=zones.map(function(z){return z.x+','+z.y}).join(' ');
      linesEl.innerHTML='<polyline points="'+pts+'" fill="none" stroke="var(--ac)" stroke-width=".5" stroke-dasharray="2,2" opacity=".4" vector-effect="non-scaling-stroke"/>';
    }else{
      linesEl.innerHTML='';
    }

    var seen={};var legItems=[];
    zones.forEach(function(z){
      var k=z.type&&ZONE_TYPES[z.type]?z.type:'other';
      if(!seen[k]){seen[k]=true;legItems.push(k);}
    });
    legEl.innerHTML=legItems.map(function(k){
      var zt=zoneType(k);
      return '<div class="lc-leg"><div class="lc-leg-dot" style="--pc:'+zt.color+'"></div>'+t([zt.en,zt.th])+'</div>';
